// Existing activities gain related destinations, while the authored actions stay unchanged.
const RELATED_SCENES = {
  patience: PLANT_PLACES, listening: WATER_PLACES.filter(id => !SCENES.find(scene => scene.id === id).tags.includes('underwater')),
  rest: locations('sky', 'outdoors'), sharing: locations('plants', 'food'), mistakes: COMFORTABLE_PLACES,
  comparison: OPEN_PLACES, 'asking-help': COMFORTABLE_PLACES, feelings: WATER_PLACES.filter(id => !SCENES.find(scene => scene.id === id).tags.includes('underwater')),
  picnic: locations('family', 'outdoors'), boats: WATER_PLACES.filter(id => !SCENES.find(scene => scene.id === id).tags.includes('underwater')),
  flowers: locations('shelter', 'plants'), blanket: COMFORTABLE_PLACES, music: COMFORTABLE_PLACES,
  'treasure-map': OPEN_PLACES, puppets: COMFORTABLE_PLACES, garden: PLANT_PLACES,
};
for (const goal of [...RELAX_GOALS, ...FRIEND_GOALS]) {
  if (RELATED_SCENES[goal.id]) goal.scenes = [...new Set([...goal.scenes, ...RELATED_SCENES[goal.id]])];
}
for (const goal of FAMILY_GOALS) {
  // Everyday family stories use walkways, gardens and welcoming places, without imposing a magical journey.
  const friendId = goal.id.replace(/^family-/, '');
  const related = RELATED_SCENES[friendId] || [];
  goal.scenes = [...new Set([...goal.scenes, ...related])].filter(id => SCENES.find(scene => scene.id === id).tags.includes('family'));
}

